<script lang="ts">
 import UnsavedChanges from '$lib/shared/presentation/ui/UnsavedChanges.svelte';
 import {fieldValidation} from '$lib/shared/presentation/form-validation';
 import QueueFilters from '$lib/shared/presentation/ui/QueueFilters.svelte';
 import {queueDepth} from '$lib/shared/presentation/queue-context';
 import {tick} from 'svelte';
 import {afterNavigate,replaceState} from '$app/navigation';
 import ProjectCover from './ProjectCover.svelte';
 import {onMount} from 'svelte';
 import {page} from '$app/stores';
 import type {Account} from '$lib/features/identity/domain/account';
 import type {TeamsGateway} from '$lib/features/teams/application/teams';
 import type {Team} from '$lib/features/teams/domain/team';
 import type {ProjectRequestsGateway} from '../application/project-requests';
 import {requestTranslation} from '../application/project-requests';
 import type {ProjectRequest,ProjectRequestInput} from '../domain/project-request';
 import RequestStatus from './RequestStatus.svelte';
 import SectionHeading from '$lib/shared/presentation/ui/SectionHeading.svelte';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode,noticeText} from '$lib/shared/presentation/copy';
 let {user,gateway,teamsGateway,admin=false}:{user:Account|null;gateway:ProjectRequestsGateway;teamsGateway:TeamsGateway;admin?:boolean}=$props();
 const {locale}=useLocale();
 let items=$state<ProjectRequest[]>([]),teams=$state<Team[]>([]),hasMore=$state(false),moreTeams=$state(false),loading=$state(true),busy=$state(false),error=$state(''),notice=$state(''),formOpen=$state(false),kind=$state('existing'),query=$state(''),results=$state<{id:string;name:string;slug:string}[]>([]),searching=$state(false),searched=$state(false),reviewID=$state(''),reason=$state('');
 function blank(teamId=''):ProjectRequestInput{return {teamId,titleId:'',name:'',originalName:'',slug:'',kind:'manhwa',description:'',sourceURL:'',note:''};}
 let depth=$state(1),selectedRequest=$state(''),requestInspector=$state(false);let requestPanel=$state<HTMLElement>();let requestTrigger:HTMLButtonElement|undefined;
 const displayedRequests=$derived(admin?items.filter(item=>item.id===(selectedRequest||items[0]?.id)):items);
 async function inspectRequest(id:string,trigger?:HTMLButtonElement){if(busy||(guard&&!guard.confirmDiscard()))return;reviewID='';reason='';selectedRequest=id;requestInspector=true;requestTrigger=trigger;await tick();requestPanel?.focus({preventScroll:true});if(window.innerWidth<1000)requestPanel?.scrollIntoView({block:'start'});}
 async function closeInspection(){if(busy||(guard&&!guard.confirmDiscard()))return;reviewID='';reason='';requestInspector=false;await tick();requestTrigger?.focus();}
 let input=$state<ProjectRequestInput>(blank());
 let guard=$state<{confirmDiscard():boolean}>(),baseline=$state(''),contextWarning=$state(''),appliedTeam='';
 const inputValue=$derived(JSON.stringify([input,kind,query]));
 const dirty=$derived((formOpen&&inputValue!==baseline)||(reviewID!==''&&reason.trim()!==''));
 function remember(){baseline=JSON.stringify([input,kind,query]);}
 function closeForm(){if(guard&&!guard.confirmDiscard())return;formOpen=false;input=blank(input.teamId);kind='existing';query='';results=[];searched=false;remember();}
 function chooseRequest(item:ProjectRequest){if(guard&&!guard.confirmDiscard())return;input={teamId:item.teamId,titleId:item.titleId,name:item.name,originalName:item.originalName,slug:item.slug,kind:item.kind,description:item.description,sourceURL:item.sourceURL,note:item.note};kind=item.titleId?'existing':'new';query='';results=item.titleId?[{id:item.titleId,name:item.titleName,slug:''}]:[];formOpen=true;remember();}
 async function teamContext(){const id=$page.url.searchParams.get('team')||'';appliedTeam=id;contextWarning='';if(id){while(!teams.some(team=>team.id===id)&&moreTeams){const batch=await teamsGateway.list(teams.length);teams=[...teams,...batch];moreTeams=batch.length===100;}const selected=teams.find(team=>team.id===id&&team.approved&&(team.role==='owner'||team.role==='editor'));input=blank(selected?.id||'');if(!selected)contextWarning='team_unavailable';}else input=blank(teams.find(team=>team.approved&&(team.role==='owner'||team.role==='editor'))?.id||'');kind='existing';query='';results=[];searched=false;formOpen=$page.url.searchParams.has('new');remember();}
 afterNavigate(()=>{if(!loading&&!admin&&appliedTeam!==($page.url.searchParams.get('team')||''))void run(teamContext);});
 const eligible=$derived(teams.filter(team=>team.approved&&(team.role==='owner'||team.role==='editor')));
 async function load(after=''){const result=await gateway.list(admin,after,admin?{team:$page.url.searchParams.get('team')||'',kind:$page.url.searchParams.get('kind')||''}:undefined);items=after?[...items,...result.items]:result.items;hasMore=result.hasMore;if(after)depth++;else depth=1;}
 onMount(()=>{if(!user){loading=false;return;}void(async()=>{try{formOpen=$page.url.searchParams.has('new');await load();if(admin){const wanted=queueDepth($page.url);for(let i=1;i<wanted&&hasMore;i++)await load(items.at(-1)?.id||'');const requested=$page.url.hash.replace('#queue-','');if(items.some(item=>item.id===requested)){selectedRequest=requested;requestInspector=true;}await tick();if($page.url.hash)document.getElementById($page.url.hash.slice(1))?.scrollIntoView();}if(!admin){teams=await teamsGateway.list();moreTeams=teams.length===100;await teamContext();}}catch(failure){error=failureCode(failure);}finally{loading=false;}})();});
 async function run(action:()=>Promise<void>){if(busy)return;busy=true;error='';notice='';try{await action();}catch(failure){error=failureCode(failure);}finally{busy=false;}}
 async function search(){searching=true;error='';try{results=await gateway.search(query.trim());searched=true;}catch(failure){error=failureCode(failure);}finally{searching=false;}}
 async function submit(event:SubmitEvent){event.preventDefault();await run(async()=>{await requestTranslation(gateway,{...input,titleId:kind==='existing'?input.titleId:''});input=blank(input.teamId);query='';kind='existing';remember();formOpen=false;await load();notice=text($locale,'Өтінім жіберілді. Шешім осы жерде және хабарларда көрінеді.','Заявка отправлена. Решение появится здесь и в уведомлениях.');});}
 async function review(item:ProjectRequest,decision:'approve'|'reject'){await run(async()=>{
  const index=items.findIndex(row=>row.id===item.id),next=items[index+1]||items[index-1];
  try{await gateway.review(item.id,decision,reason);notice=decision==='approve'?text($locale,'Жоба командаға берілді.','Проект выдан команде.'):text($locale,'Өтінім себеппен қайтарылды.','Заявка возвращена с причиной.');}
  catch(failure){if(failureCode(failure)!=='conflict')throw failure;notice=text($locale,'Бұл өтінім бойынша шешім қабылданған. Келесі өтінімді тексер.','По этой заявке уже приняли решение. Перейди к следующей.');}
  reviewID='';reason='';selectedRequest=next?.id||'';items=items.filter(row=>row.id!==item.id);await tick();if(next){const row=document.getElementById('queue-'+next.id);row?.focus();row?.scrollIntoView({block:'center'});}
 });}
 async function moreRequests(){await load(items.at(-1)?.id||'');if(admin){const next=new URL(window.location.href);next.searchParams.set('loaded',String(depth));replaceState(next.pathname+next.search+next.hash,$page.state);}}

</script>
<UnsavedChanges {dirty} bind:this={guard}/>
<svelte:head><title>{text($locale,'Аударма өтінімдері','Заявки на перевод')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
<SectionHeading level={1} title={admin?text($locale,'Жоба өтінімдері','Заявки на проекты'):text($locale,'Өтінімдерім','Мои заявки')} description={admin?text($locale,'Мақұлдау командаға жобаны береді. Жаңа тайтл жарияланбайды: алдымен тарау тексеріледі.','Одобрение выдаёт проект команде. Новый тайтл остаётся черновиком до публикации главы.'):text($locale,'Каталогтағы тайтлды аударуға сұрау жібер немесе жаңа шығарма ұсын.','Запроси перевод тайтла из каталога или предложи новое произведение.')}>
 {#snippet actions()}{#if user&&!admin&&!formOpen}<button class="button primary" onclick={()=>formOpen=true}>{text($locale,'Өтінім жіберу','Подать заявку')}</button>{/if}{/snippet}
</SectionHeading>
{#if !user}<div class="empty-state"><h2>{text($locale,'Алдымен аккаунтқа кір','Войди в аккаунт')}</h2><p>{text($locale,'Өтінімдер команда атынан жіберіледі.','Заявки отправляются от имени команды.')}</p><a class="button primary" href="/login?returnTo=%2Fstudio%2Frequests">{text($locale,'Кіру','Войти')}</a></div>
{:else if admin&&user.role!=='admin'}<p>{text($locale,'Әкімші рұқсаты қажет.','Нужен доступ администратора.')}</p>
{:else}
 {#if error}<p class="form-message" role="alert">{noticeText($locale,error)}</p>{#if !busy}<button class="button subtle" onclick={()=>run(()=>load())}>{text($locale,'Қайталау','Повторить')}</button>{/if}{/if}
 {#if notice}<p class="form-message success" role="status">{notice}</p>{/if}
 {#if admin}<QueueFilters kinds={[{value:'new',kk:'Жаңа шығарма',ru:'Новое произведение'},{value:'existing',kk:'Каталогтағы тайтл',ru:'Тайтл из каталога'}]}/>{/if}
 {#if loading}<p role="status">{text($locale,'Өтінімдер жүктелуде…','Загружаем заявки…')}</p>
 {:else}
  {#if !admin&&formOpen}<section class="request-form"><div class="form-heading"><h2>{text($locale,'Жаңа өтінім','Новая заявка')}</h2><button type="button" class="button subtle" disabled={busy} onclick={closeForm}>{text($locale,'Жабу','Закрыть')}</button></div>
   {#if !eligible.length}<p>{text($locale,'Өтінім жіберу үшін мақұлданған командада иесі не редактор болуың керек.','Для заявки нужна одобренная команда, в которой ты владелец или редактор.')}</p><a class="button primary" href="/studio/teams">{text($locale,'Командаларға өту','Перейти к командам')}</a>
   {:else}<form use:fieldValidation={{locale:$locale}} onsubmit={submit}>
    {#if contextWarning}<p class="form-message" role="status">{text($locale,'Таңдалған командаға өтінім беру мүмкін емес. Команда мақұлданған болуы және сен иесі не редактор болуың керек. Басқа команданы өзің таңда.','Для выбранной команды нельзя подать заявку: нужны одобрение и роль владельца или редактора. Выбери другую команду явно.')}</p>{/if}<label>{text($locale,'Команда','Команда')}<select bind:value={input.teamId} required><option value="" disabled>{text($locale,'Команданы таңда','Выбери команду')}</option>{#each eligible as team}<option value={team.id}>{team.name}</option>{/each}</select></label>
    <label>{text($locale,'Не аударғың келеді?','Что хочешь переводить?')}<select bind:value={kind} onchange={()=>{input.titleId='';results=[];searched=false;}}><option value="existing">{text($locale,'Каталогтағы тайтл','Тайтл из каталога')}</option><option value="new">{text($locale,'Жаңа шығарма ұсыну','Предложить новое произведение')}</option></select></label>
    {#if kind==='existing'}<div class="search"><label>{text($locale,'Тайтл атауы','Название тайтла')}<input type="search" bind:value={query} maxlength="80" placeholder={text($locale,'Атауы немесе балама атауы','Название или альтернативное название')}/></label><button type="button" class="button subtle" disabled={searching||query.trim().length<2} onclick={search}>{searching?text($locale,'Ізделуде…','Ищем…'):text($locale,'Іздеу','Найти')}</button></div>
     {#if results.length}<fieldset><legend>{text($locale,'Тайтлды таңда','Выбери тайтл')}</legend>{#each results as title}<label class="choice"><input type="radio" bind:group={input.titleId} value={title.id}/><span>{title.name}</span>{#if title.slug}<a href={'/titles/'+title.slug} target="_blank" rel="noreferrer" aria-label={text($locale,title.name+' — тайтлды ашу',title.name+' — открыть тайтл')}>↗</a>{/if}</label>{/each}</fieldset>{:else if searched}<p>{text($locale,'Табылмады. «Жаңа шығарма ұсыну» нұсқасын таңда.','Не найдено. Выбери «Предложить новое произведение».')}</p>{/if}
    {:else}<label>{text($locale,'Қазақша атауы','Название на казахском')}<input bind:value={input.name} required maxlength="200"/></label><label>{text($locale,'Түпнұсқа атауы','Оригинальное название')}<input bind:value={input.originalName} maxlength="200"/></label><label>{text($locale,'Түрі','Тип')}<select bind:value={input.kind}><option value="manhwa">Манхва</option><option value="manga">Манга</option><option value="manhua">Маньхуа</option></select></label><label>{text($locale,'Қысқаша сипаттама','Краткое описание')}<textarea bind:value={input.description} maxlength="10000" rows="4"></textarea></label>{/if}
    <label>{text($locale,'Дереккөз сілтемесі','Ссылка на источник')}<input type="url" bind:value={input.sourceURL} maxlength="2000" placeholder="https://…"/></label>
    <label>{text($locale,'Команда жоспары','Планы команды')}<textarea bind:value={input.note} minlength="8" maxlength="2000" rows="3" required placeholder={text($locale,'Қайдан аударасыңдар, не дайын, қалай шығарасыңдар?','Откуда переводите, что уже готово, как планируете выпускать?')}></textarea></label>
    <p class="muted">{text($locale,'Өтінім сайтқа ештеңе жарияламайды. Бір командадан 5 өтінімге дейін қаралады.','Заявка ничего не публикует на сайте. Одновременно рассматриваются до 5 заявок команды.')}</p>
    <button type="submit" class="button primary" disabled={busy||kind==='existing'&&!input.titleId}>{busy?text($locale,'Жіберілуде…','Отправляем…'):text($locale,'Қарауға жіберу','Отправить на рассмотрение')}</button>
   </form>{/if}
   {#if moreTeams}<button class="button subtle" disabled={busy} onclick={()=>run(async()=>{const batch=await teamsGateway.list(teams.length);teams=[...teams,...batch];moreTeams=batch.length===100;})}>{text($locale,'Тағы командалар','Ещё команды')}</button>{/if}
  </section>{/if}
  <div class:admin-workbench={admin}>{#if admin}<section class="request-list" aria-label={text($locale,'Өтінімдер кезегі','Очередь заявок')}>{#each items as item (item.id)}<button class="request-summary" class:chosen={displayedRequests[0]?.id===item.id} aria-pressed={displayedRequests[0]?.id===item.id} disabled={busy} onclick={event=>void inspectRequest(item.id,event.currentTarget)}><strong>{item.titleName||item.name}</strong><span>{item.teamName}</span><small>{new Date(item.createdAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ')} · {item.titleId?text($locale,'Каталогтағы тайтл','Тайтл из каталога'):text($locale,'Жаңа тайтл','Новый тайтл')}</small></button>{:else}<p class="empty-state">{text($locale,'Қаралатын өтінім жоқ','Нет заявок на рассмотрении')}</p>{/each}</section>{/if}<div class="requests" class:request-inspector={admin} class:visible={requestInspector} bind:this={requestPanel} tabindex="-1">{#if admin}<button class="button subtle request-back" disabled={busy} onclick={()=>void closeInspection()}>{text($locale,'Кезекке оралу','Вернуться к очереди')}</button>{/if}{#each displayedRequests as item}<article id={'queue-'+item.id} tabindex="-1"><ProjectCover url={item.coverURL} name={item.titleName||item.name}/><div class="request-content"><div class="request-heading"><h2>{item.titleName||item.name}</h2><RequestStatus status={item.status}/></div><p class="muted">{item.teamName} · {new Date(item.createdAt).toLocaleDateString($locale==='ru'?'ru-RU':'kk-KZ')}</p><p class="request-note">{item.note}</p>
   {#if item.resolution}<div class="resolution"><strong>{text($locale,'Шешімнің себебі','Причина решения')}</strong><p>{item.resolution}</p></div>{/if}
   {#if admin}<details><summary>{text($locale,'Өтінім деректері','Данные заявки')}</summary><p>{item.originalName}</p><p>{item.description}</p>{#if item.sourceURL}<a class="auth-link" href={item.sourceURL} target="_blank" rel="noreferrer">{text($locale,'Дереккөзді ашу','Открыть источник')} ↗</a>{/if}<p>{item.titleId?text($locale,'Каталогтағы тайтл','Тайтл из каталога'):text($locale,'Жаңа тайтл жасалады','Будет создан новый тайтл')}</p></details><div class="actions"><button class="button primary" disabled={busy} onclick={()=>{if(guard&&!guard.confirmDiscard())return;reason='';void review(item,'approve');}}>{text($locale,'Жоба беру','Выдать проект')}</button><button class="button subtle" disabled={busy} onclick={()=>{if(guard&&!guard.confirmDiscard())return;reviewID=item.id;reason='';}}>{text($locale,'Қайтару','Вернуть')}</button></div>
    {#if reviewID===item.id}<form class="review" use:fieldValidation={{locale:$locale}} onsubmit={event=>{event.preventDefault();void review(item,'reject');}}><label>{text($locale,'Не түзету керек?','Что нужно исправить?')}<textarea bind:value={reason} minlength="8" maxlength="2000" required rows="3"></textarea></label><div class="actions"><button class="button primary" disabled={busy}>{text($locale,'Себеппен қайтару','Вернуть с причиной')}</button><button type="button" class="button subtle" onclick={()=>{if(guard&&!guard.confirmDiscard())return;reviewID='';reason='';}}>{text($locale,'Бас тарту','Отмена')}</button></div></form>{/if}
   {:else}<div class="actions">{#if item.projectId}<a class="button primary" href={'/studio/projects/'+item.projectId}>{text($locale,'Жобаны ашу','Открыть проект')}</a>{:else if item.status==='pending'&&eligible.some(team=>team.id===item.teamId)}<button class="button subtle" disabled={busy} onclick={()=>run(async()=>{await gateway.cancel(item.id);await load();})}>{text($locale,'Өтінімді тоқтату','Отменить заявку')}</button>{:else if item.status==='rejected'}<button class="button subtle" onclick={()=>chooseRequest(item)}>{text($locale,'Түзетіп қайта жіберу','Исправить и отправить снова')}</button>{/if}</div>{/if}
  </div></article>{:else}<div class="empty-state"><h2>{admin?text($locale,'Қаралатын өтінім жоқ','Нет заявок на рассмотрении'):text($locale,'Әзірге өтінім жоқ','Заявок пока нет')}</h2><p>{admin?text($locale,'Командалардың жоба сұраулары осында түседі.','Здесь появятся запросы команд на проекты.'):text($locale,'Жоба керек болса, жоғарыдағы батырмамен өтінім жібер.','Чтобы получить проект, подай заявку кнопкой выше.')}</p></div>{/each}</div></div>
  {#if hasMore}<button class="button subtle" disabled={busy} onclick={()=>run(moreRequests)}>{text($locale,'Тағы жүктеу','Загрузить ещё')}</button>{/if}
 {/if}
{/if}
<style>
 .admin-workbench{display:grid;gap:24px;align-items:start}.request-list{display:grid;gap:10px;min-width:0}.request-summary{display:grid;gap:8px;text-align:start;min-height:88px;padding:18px;border:1px solid var(--line);border-radius:10px;background:var(--panel);color:var(--text);overflow-wrap:anywhere}.request-summary.chosen{background:var(--raised)}.request-summary span,.request-summary small{color:var(--muted);font-size:12px}.request-inspector{min-width:0;scroll-margin-top:88px}.request-inspector article{margin:0}.request-back{justify-self:start}@media(min-width:1000px){.admin-workbench{grid-template-columns:minmax(260px,1fr) minmax(0,1.4fr)}.request-inspector{position:sticky;top:88px}.request-back{display:none}}@media(max-width:999px){.request-inspector{display:none}.request-inspector.visible{display:grid}}
 .request-form{max-width:760px;padding:20px;border:1px solid var(--line);margin-bottom:28px}.form-heading,.request-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap}h2{font-size:18px;margin:0;overflow-wrap:anywhere}form{display:grid;gap:16px;margin-top:20px}label{display:grid;gap:8px;font-size:14px;min-width:0}.search{display:flex;align-items:end;gap:8px}.search label{flex:1;min-width:0}fieldset{padding:12px;border:1px solid var(--line);min-width:0}legend{padding:0 6px;font-size:14px}.choice{display:flex;align-items:center;min-height:48px;gap:12px;padding:8px 0}.choice input{width:20px;height:20px;min-height:20px;flex:none}.choice span{flex:1;overflow-wrap:anywhere}.choice a{display:flex;align-items:center;justify-content:center;min-width:44px;min-height:44px}.requests{max-width:840px;display:grid;gap:12px}article{display:flex;gap:14px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.request-content{min-width:0;flex:1}.muted{font-size:14px;margin:8px 0}.request-note,.resolution p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.6}.resolution{border-left:2px solid var(--line);padding:4px 16px;margin:16px 0}.resolution strong{font-size:14px}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:16px}summary{cursor:pointer;min-height:44px;display:flex;align-items:center;color:var(--muted)}details p{white-space:pre-wrap;overflow-wrap:anywhere}.review{max-width:640px}button[type=submit]{justify-self:start}@media(max-width:420px){.request-form{padding:16px 12px}.search{flex-wrap:wrap}.search label{flex-basis:100%}}
</style>
